    objectives: [{ t: 'collect', item: 'q_traumscherbe', n: 5, label: 'Traumscherben von den Geschöpfen des Quellgrunds sammeln' }, { t: 'echo', id: 'stille1', label: 'Den Vorboten der Stille vor dem Tor zum Herzen bezwingen' }],
